def generate_signals(df: pd.DataFrame) -> pd.Series:
    sma_60 = df['close'].rolling(window=60).mean()
    signals = pd.Series(0, index=df.index)
    in_position = False
    closes = df['close'].values
    smas = sma_60.values

    for i in range(len(df)):
        if np.isnan(smas[i]):
            continue
        if not in_position:
            if closes[i] < smas[i] * 0.95:
                signals.iloc[i] = 1
                in_position = True
        else:
            if closes[i] >= smas[i]:
                signals.iloc[i] = 0
                in_position = False
    return signals

def generate_signals(df: pd.DataFrame) -> pd.Series:
    signals = pd.Series(0, index=df.index)
    in_position = False
    c = df['close'].values
    n = len(c)
    for i in range(n):
        if i < 3:
            continue
        if not in_position:
            if c[i] < c[i-1] and c[i-1] < c[i-2] and c[i-2] < c[i-3]:
                in_position = True
        if in_position:
            signals.iloc[i] = 1
            if c[i] > c[i-1]:
                in_position = False
    return signals
